public int Add(int a, int b)
{
    int sum = a + b;
    return sum;
}

int Multiply(int a, int b)
{
    return a * b;
}

int result = Multiply(3, 4); // 12

void PrintSum(int a, int b)
{
    Console.WriteLine(a + b);
}

PrintSum(5, 3); // 8

void Greet(string name)
{
    Console.WriteLine("Hi, " + name);
}

Greet("Alice");
Greet("Bob");

void Print(int num) { Console.WriteLine(num); }
void Print(string text) { Console.WriteLine(text); }
void Print(int a, int b) { Console.WriteLine(a + b); }

Print(10);      // 10
Print("Hi");   // Hi
Print(2, 3);   // 5

void SetAge(int age) // age is a parameter
{
    Console.WriteLine(age);
}

SetAge(25); // 25 is an argument

int GetArea(int width, int height)
{
    return width * height;
}

int area = GetArea(5, 4);
Console.WriteLine(area); // 20

